from pathlib import Path
import json

MAX_FILES_PER_DIR = 30
MAX_FILE_SIZE = 15 * 1024 * 1024
BASE = MAX_FILES_PER_DIR
CHUNK_ID_WIDTH = 5
MAX_CHUNKS = BASE ** CHUNK_ID_WIDTH

DATA_DIR_NAME = "data"
META_DIR_NAME = "meta"
MANIFEST_NAME = "manifest.json"
DATA_SUFFIX = ".bin"
META_SUFFIX = ".jsonl"

_DIGIT_NAMES = [f"{i:02d}" for i in range(BASE)]


def chunk_path(base_dir: Path, chunk_id: int, width: int, suffix: str) -> Path:
    if chunk_id < 0:
        raise ValueError("chunk_id must be non-negative")
    if width <= 0:
        raise ValueError("width must be positive")
    if chunk_id >= BASE ** width:
        raise ValueError("chunk_id exceeds width capacity")
    digits = []
    remaining = chunk_id
    for _ in range(width):
        digits.append(remaining % BASE)
        remaining //= BASE
    path = Path(base_dir)
    for digit in reversed(digits[:-1]):
        path = path / _DIGIT_NAMES[digit]
    filename = f"{_DIGIT_NAMES[digits[-1]]}{suffix}"
    return path / filename


def json_dumps(obj: object) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def json_line_bytes(obj: object) -> bytes:
    return (json_dumps(obj) + "\n").encode("utf-8")
"}

