{"path": "/app/decompress.py", "content": "from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
from typing import Dict, Iterator, Tuple

from reshard_utils import (
    DATA_DIR_NAME,
    DATA_SUFFIX,
    MANIFEST_NAME,
    META_DIR_NAME,
    META_SUFFIX,
    chunk_path,
    json_dumps,
)


def iter_chunk_paths(base_dir: Path, suffix: str) -> Iterator[Path]:
    for root, _, files in os.walk(base_dir):
        root_path = Path(root)
        for name in sorted(files):
            if name.endswith(suffix):
                yield root_path / name


def read_meta_entries(meta_dir: Path) -> Iterator[Dict[str, object]]:
    for path in iter_chunk_paths(meta_dir, META_SUFFIX):
        with open(path, "rb") as handle:
            for line in handle:
                if not line:
                    continue
                entry = json.loads(line.decode("utf-8"))
                yield entry


def reconstruct_file(base_dir: Path, entry: Dict[str, object]) -> None:
    rel_path = entry["path"]
    size = entry["size"]
    sha256 = entry["sha256"]
    data_ref = entry["data"]
    data_path = base_dir / data_ref["path"]
    offset = int(data_ref["offset"])
    length = int(data_ref["length"])

    with open(data_path, "rb") as handle:
        handle.seek(offset)
        payload = handle.read(length)

    if len(payload) != size:
        raise RuntimeError(f"Size mismatch for {rel_path}")

    digest = hashlib.sha256(payload).hexdigest()
    if digest != sha256:
        raise RuntimeError(f"Checksum mismatch for {rel_path}")

    target_path = base_dir / rel_path
    target_path.parent.mkdir(parents=True, exist_ok=True)
    with open(target_path, "wb") as handle:
        handle.write(payload)


def reconstruct_dir(base_dir: Path, entry: Dict[str, object]) -> None:
    rel_path = entry["path"]
    target_path = base_dir / rel_path
    target_path.mkdir(parents=True, exist_ok=True)


def decompress(resharded_dir: Path) -> None:
    resharded_dir = resharded_dir.resolve()
    manifest_path = resharded_dir / MANIFEST_NAME
    if not manifest_path.exists():
        raise SystemExit(f"Manifest file {manifest_path} is missing")
    manifest = json.loads(manifest_path.read_text())
    if manifest.get("format") != "reshard-v1":
        raise SystemExit("Unsupported reshard format")

    data_dir = resharded_dir / manifest.get("data_dir", DATA_DIR_NAME)
    meta_dir = resharded_dir / manifest.get("meta_dir", META_DIR_NAME)
    if not data_dir.exists() or not meta_dir.exists():
        raise SystemExit("Missing data or meta directory")

    for entry in read_meta_entries(meta_dir):
        entry_type = entry.get("type")
        if entry_type == "dir":
            reconstruct_dir(resharded_dir, entry)
        elif entry_type == "file":
            reconstruct_file(resharded_dir, entry)
        else:
            raise RuntimeError("Unknown entry type")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Reconstruct resharded dataset in place.")
    parser.add_argument("resharded_dir", type=Path)
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    if not args.resharded_dir.exists():
        raise SystemExit(f"Directory {args.resharded_dir} does not exist")
    decompress(args.resharded_dir)


if __name__ == "__main__":
    main()
"}

